from lxml import objectify
from taf.internal.scf.tree_object import TreeListObject
from taf.internal.scf.p import P
from taf.internal.scf.item import Item
from taf.internal.scf.exceptions import ElementNotFound


class List(TreeListObject):
    def __init__(self, tree=None):
        super(List, self).__init__(tree)

    def __getattr__(self, item):
        if item.startswith("__"):
            return super(List, self).__getattr__(item)
        try:
            return self.find_element(item, self._tree.item)
        except IndexError:
            raise ElementNotFound("Element {item} not found.".format(item=item))

    class ListIterator:
        def __init__(self, tree):
            self._tree = tree
            self._current_index = 0

        def __next__(self):
            index = self._current_index
            classes = [('item', Item), ('p', P)]
            try:
                child = self._tree.getchildren()[index]
                result = TreeListObject.return_scf_element(child, classes)
                self._current_index += 1
                return result
            except IndexError:
                self._current_index = 0
                raise StopIteration

        def next(self):
            return self.__next__()

        def __iter__(self):
            return self

    def __iter__(self):
        return List.ListIterator(self._tree)

    def __getitem__(self, item):
        classes = [('item', Item), ('p', P)]
        return self._get_children(item, self._tree, classes)

    def __len__(self):
        return len(self._tree.getchildren())

    def create(self, name, ns='raml21.xsd'):
        element = objectify.ObjectifiedElement()
        element.tag = '{' + ns + '}list'
        element.attrib['name'] = name
        self._tree = element
        return self
